//! collab/mail.rs —— 邮箱验证码(注册 / 找回密码)与 SMTP 发信。
//!
//! 配置两级:环境变量 POLARIS_SMTP_*(部署态,Docker -e 注入)优先,
//! 其次 collab.db meta 表(owner 在「邮箱服务设置」面板里填,桌面主机免环境变量)。
//! QQ 邮箱:host=smtp.qq.com,port=465(隐式 TLS),user=你的QQ邮箱,
//! pass=**SMTP 授权码**(不是 QQ 密码,须账号主人在 QQ 邮箱「设置→账号」开启 SMTP 领取)。
//!
//! 安全口径:
//! - 明文验证码只进邮件,库里存 argon2id 哈希;10 分钟过期,5 次错误即作废。
//! - 同邮箱 60s 内不重发,每小时最多 5 次请求(落库,包括提醒及不发信请求)。
//! - SMTP 密码读取后不回显(admin 面板只给「已配置」掩码)。
#![cfg(feature = "collab-host")]

use lettre::message::header::ContentType;
use lettre::transport::smtp::authentication::Credentials;
use lettre::{Message, SmtpTransport, Transport};
use rusqlite::params;

mod requests;
pub use requests::CodeRequest;

pub const INVALID_CODE: &str = "验证码无效或已过期";

use super::auth;
use super::db::{self, now, open_db};

/// 验证码有效期(秒)。
const CODE_TTL: i64 = 10 * 60;
/// 同邮箱重发间隔(秒)。
const RESEND_GAP: i64 = 60;
/// 每邮箱每小时发信上限。
const HOURLY_CAP: usize = 5;
/// 单枚验证码最大试错次数。
const MAX_ATTEMPTS: i64 = 5;

#[derive(Clone)]
pub struct SmtpCfg {
    pub host: String,
    pub port: u16,
    pub user: String,
    pub pass: String,
    pub from: String,
}

fn env_nonempty(k: &str) -> Option<String> {
    std::env::var(k).ok().map(|s| s.trim().to_string()).filter(|s| !s.is_empty())
}

fn meta_nonempty(k: &str) -> Option<String> {
    db::meta_get(k).map(|s| s.trim().to_string()).filter(|s| !s.is_empty())
}

/// 读当前 SMTP 配置(env 优先,meta 兜底)。user+pass 齐了才算配置完成。
pub fn config() -> Option<SmtpCfg> {
    let user = env_nonempty("POLARIS_SMTP_USER").or_else(|| meta_nonempty("smtp_user"))?;
    let pass = env_nonempty("POLARIS_SMTP_PASS").or_else(|| meta_nonempty("smtp_pass"))?;
    let host = env_nonempty("POLARIS_SMTP_HOST")
        .or_else(|| meta_nonempty("smtp_host"))
        .unwrap_or_else(|| "smtp.qq.com".into());
    let port = env_nonempty("POLARIS_SMTP_PORT")
        .or_else(|| meta_nonempty("smtp_port"))
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(465);
    let from = env_nonempty("POLARIS_SMTP_FROM")
        .or_else(|| meta_nonempty("smtp_from"))
        .unwrap_or_else(|| user.clone());
    Some(SmtpCfg { host, port, user, pass, from })
}

pub fn configured() -> bool {
    config().is_some()
}

/// 邮箱自助注册是否开放:SMTP 配置齐 + 未被显式关闭
/// (env POLARIS_EMAIL_SIGNUP=0 或 meta email_signup=0 都能关;默认开)。
pub fn signup_open() -> bool {
    if !configured() {
        return false;
    }
    if let Ok(v) = std::env::var("POLARIS_EMAIL_SIGNUP") {
        if v == "0" || v.eq_ignore_ascii_case("false") {
            return false;
        }
    }
    db::meta_get("email_signup").map(|v| v != "0").unwrap_or(true)
}

/// owner 面板保存配置(写 meta;空 pass 表示保留旧授权码不动)。
pub fn save_config(
    host: &str,
    port: u16,
    user: &str,
    pass: &str,
    from: &str,
    signup: bool,
) -> Result<(), String> {
    db::meta_set("smtp_host", host.trim())?;
    db::meta_set("smtp_port", &port.to_string())?;
    db::meta_set("smtp_user", user.trim())?;
    if !pass.trim().is_empty() {
        db::meta_set("smtp_pass", pass.trim())?;
    }
    db::meta_set("smtp_from", from.trim())?;
    db::meta_set("email_signup", if signup { "1" } else { "0" })?;
    Ok(())
}

/// 发一封纯文本信。阻塞(SMTP 往返数秒),调用方须放 spawn_blocking。
pub fn send_mail(to: &str, subject: &str, body: &str) -> Result<(), String> {
    let cfg = config().ok_or("邮箱服务未配置:请管理员先在「邮箱服务设置」填好 SMTP")?;
    let from = format!("Polaris 设备联盟 <{}>", cfg.from);
    let msg = Message::builder()
        .from(from.parse().map_err(|e| format!("发件人地址无效: {e}"))?)
        .to(to.parse().map_err(|e| format!("收件人地址无效: {e}"))?)
        .subject(subject)
        .header(ContentType::TEXT_PLAIN)
        .body(body.to_string())
        .map_err(|e| format!("组信失败: {e}"))?;
    // 465 = 隐式 TLS(QQ 邮箱默认);587 等其他端口走 STARTTLS。
    let builder = if cfg.port == 465 {
        SmtpTransport::relay(&cfg.host)
    } else {
        SmtpTransport::starttls_relay(&cfg.host)
    }
    .map_err(|e| format!("SMTP 连接器创建失败: {e}"))?;
    let mailer = builder
        .port(cfg.port)
        .credentials(Credentials::new(cfg.user.clone(), cfg.pass.clone()))
        .timeout(Some(std::time::Duration::from_secs(20)))
        .build();
    mailer
        .send(&msg)
        .map(|_| ())
        .map_err(|e| format!("发信失败(检查 SMTP 授权码/网络): {e}"))
}

fn gen_code() -> Result<String, String> {
    let mut b = [0u8; 4];
    getrandom::getrandom(&mut b).map_err(|e| format!("生成验证码失败: {e}"))?;
    Ok(format!("{:06}", u32::from_le_bytes(b) % 1_000_000))
}

/// 发码频控。**落库**(见 [`db::rate_gate`]),两道闸都要过:
///  · 按邮箱:防对着一个账号反复要码。
///  · 按来源 IP:防换邮箱轰炸 —— 只按邮箱计数的话,攻击者每次换个地址就能接着打,
///    我们的 SMTP 就成了免费邮件炮台(还会把发信域名打进黑名单)。
///
/// `ip` 传空(拿不到来源,比如内部调用)时只走邮箱那道闸,不误伤。
fn rate_check(email: &str, ip: &str) -> Result<(), String> {
    // 60 秒重发间隔:单独判,好给「请一分钟后再试」这句更准的话。
    if db::rate_since(SCOPE_EMAIL, email).is_some_and(|d| d < RESEND_GAP) {
        return Err("发送太频繁,请一分钟后再试".into());
    }
    db::rate_gate(
        SCOPE_EMAIL,
        email,
        HOURLY_CAP as i64,
        3600,
        "这个邮箱一小时内发送次数已达上限,请稍后再试",
    )?;
    // IP 闸比邮箱闸宽(一个办公室/家庭出口后面可能真有几个人同时注册),但足以掐死轰炸。
    db::rate_gate(
        SCOPE_IP,
        ip,
        IP_HOURLY_CAP,
        3600,
        "当前网络的验证码请求过于频繁,请稍后再试",
    )
}

const SCOPE_EMAIL: &str = "email";
const SCOPE_IP: &str = "ip";
/// 同一来源 IP 每小时的发码上限。
const IP_HOURLY_CAP: i64 = 20;

/// 生成并发送验证码(purpose: signup|reset|login)。阻塞,须放 spawn_blocking。
///
/// `ip` = 请求来源(拿不到就传空串)。它只用于频控,不落业务表。
pub fn issue_code_from(email: &str, purpose: &str, ip: &str) -> Result<(), String> {
    let email = auth::validate_email(email)?;
    rate_check(&email, ip)?;
    deliver_code(&email, purpose, send_mail)
}

fn deliver_code(
    email: &str,
    purpose: &str,
    sender: impl FnOnce(&str, &str, &str) -> Result<(), String>,
) -> Result<(), String> {
    let code = gen_code()?;
    let phc = auth::hash_password(&code)?;
    // 文案要如实说明这封信是干什么用的 —— 收信人据此判断「这是不是我本人在操作」,
    // 把登录码写成「找回密码」会让人放过一次真正的盗号尝试。
    let action = match purpose {
        "signup" => "注册账号",
        "login" => "登录",
        _ => "找回密码",
    };
    let body = format!(
        "你正在 Polaris 设备联盟{action},验证码:\n\n    {code}\n\n10 分钟内有效。如果这不是你本人的操作,请忽略这封邮件。"
    );
    // 先发信后落库:失败不替换旧码;频控已计入请求,重试仍须等重发间隔。
    sender(email, &format!("【Polaris】{action}验证码 {code}"), &body)?;
    let t = now();
    let conn = open_db()?;
    conn.execute(
        "INSERT INTO email_codes(email,purpose,code_hash,attempts,created_at,expires_at) \
         VALUES(?1,?2,?3,0,?4,?5) \
         ON CONFLICT(email,purpose) DO UPDATE SET code_hash=excluded.code_hash, \
         attempts=0, created_at=excluded.created_at, expires_at=excluded.expires_at",
        params![email, purpose, phc, t, t + CODE_TTL],
    )
    .map_err(|e| format!("验证码落库失败: {e}"))?;
    Ok(())
}

/// 兼容无来源 IP 的内部调用;匿名 HTTP 使用 CodeRequest 分离请求与后台投递。
pub fn issue_code(email: &str, purpose: &str) -> Result<(), String> {
    issue_code_from(email, purpose, "")
}

/// 校验验证码:过期/超试错即作废,校验成功即销毁(一次性)。
pub fn verify_code(email: &str, purpose: &str, code: &str) -> Result<(), String> {
    let email = auth::validate_email(email)?;
    let code = code.trim();
    if code.is_empty() {
        return Err(INVALID_CODE.into());
    }
    // 无记录/过期/耗尽也做一次同参数 Argon2,避免用错误码请求的耗时探测账号。
    let invalid = || -> Result<(), String> {
        auth::hash_password(code)?;
        Err(INVALID_CODE.into())
    };
    let conn = open_db()?;
    let row = conn.query_row(
        "SELECT code_hash,attempts,expires_at FROM email_codes WHERE email=?1 AND purpose=?2",
        params![email, purpose],
        |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, i64>(1)?,
                r.get::<_, i64>(2)?,
            ))
        },
    );
    let (phc, attempts, expires_at) = match row {
        Ok(v) => v,
        Err(_) => return invalid(),
    };
    let gone = |conn: &rusqlite::Connection| {
        let _ = conn.execute(
            "DELETE FROM email_codes WHERE email=?1 AND purpose=?2",
            params![email, purpose],
        );
    };
    if now() > expires_at {
        gone(&conn);
        return invalid();
    }
    if attempts >= MAX_ATTEMPTS {
        gone(&conn);
        return invalid();
    }
    if !auth::verify_password(code, &phc) {
        let _ = conn.execute(
            "UPDATE email_codes SET attempts=attempts+1 WHERE email=?1 AND purpose=?2",
            params![email, purpose],
        );
        return Err(INVALID_CODE.into());
    }
    gone(&conn);
    if purpose == "signup" && auth::find_user_by_email(&email)?.is_some() {
        return Err(INVALID_CODE.into());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_db() -> std::sync::MutexGuard<'static, ()> {
        let g = super::super::db::TEST_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let p = std::env::temp_dir().join(format!(
            "collab-mail-test-{}-{}.db",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::env::set_var("POLARIS_COLLAB_DB", p);
        g
    }

    /// 不真发信:直接落一枚已知码,验证「校验-销毁-试错」状态机。
    fn plant_code(email: &str, purpose: &str, code: &str, expires_in: i64) {
        let phc = auth::hash_password(code).unwrap();
        let t = now();
        let conn = open_db().unwrap();
        conn.execute(
            "INSERT INTO email_codes(email,purpose,code_hash,attempts,created_at,expires_at) \
             VALUES(?1,?2,?3,0,?4,?5) \
             ON CONFLICT(email,purpose) DO UPDATE SET code_hash=excluded.code_hash, \
             attempts=0, created_at=excluded.created_at, expires_at=excluded.expires_at",
            params![email, purpose, phc, t, t + expires_in],
        )
        .unwrap();
    }

    #[test]
    fn verify_flow_one_shot_and_attempts() {
        let _g = tmp_db();
        plant_code("a@qq.com", "signup", "123456", 600);
        assert!(verify_code("a@qq.com", "signup", "000000").is_err());
        assert!(verify_code("a@qq.com", "signup", "123456").is_ok());
        // 一次性:用过即销毁
        assert!(verify_code("a@qq.com", "signup", "123456").is_err());
        // 试错闸:5 次错后作废
        plant_code("b@qq.com", "reset", "654321", 600);
        for _ in 0..5 {
            assert!(verify_code("b@qq.com", "reset", "999999").is_err());
        }
        let e = verify_code("b@qq.com", "reset", "654321").unwrap_err();
        assert_eq!(e, INVALID_CODE);
    }

    #[test]
    fn verify_expired_code_rejected() {
        let _g = tmp_db();
        plant_code("c@qq.com", "signup", "123456", -1);
        let e = verify_code("c@qq.com", "signup", "123456").unwrap_err();
        assert!(e.contains("过期"), "{e}");
    }

    #[test]
    fn email_validation_and_rate_gate() {
        let _g = tmp_db();
        assert!(auth::validate_email("好@qq").is_err());
        assert!(auth::validate_email("a b@qq.com").is_err());
        assert_eq!(auth::validate_email(" A@QQ.com ").unwrap(), "a@qq.com");
        // 频控:同邮箱 60s 内第二次直接拒(不真发信,rate_check 在 send 之前)。
        assert!(rate_check("gate@qq.com", "1.2.3.4").is_ok());
        let e = rate_check("gate@qq.com", "1.2.3.4").unwrap_err();
        assert!(e.contains("频繁"), "{e}");
        // 换个邮箱仍是同一个 IP —— 打满 IP 闸之后照样拒。这是「换邮箱就能接着轰炸」那个洞。
        for i in 0..IP_HOURLY_CAP {
            let _ = rate_check(&format!("burst{i}@qq.com"), "9.9.9.9");
        }
        let e = rate_check("last@qq.com", "9.9.9.9").unwrap_err();
        assert!(e.contains("网络"), "IP 闸没生效: {e}");
    }
}
use super::*;
use crate::collab::{auth, db, interconnect::test_env::TestEnv, mail};
use parking_lot::Mutex;

type Letters = Arc<Mutex<Vec<(String, String, String)>>>;

struct Fixture {
    previous: Vec<(&'static str, Option<std::ffi::OsString>)>,
    _env: TestEnv,
}

impl Fixture {
    fn new() -> Result<Self, String> {
        let env = TestEnv::new("email-privacy")?;
        let mut fixture = Self { previous: vec![], _env: env };
        for key in ["POLARIS_SMTP_USER", "POLARIS_SMTP_PASS", "POLARIS_EMAIL_SIGNUP",
            "POLARIS_ACCOUNT_OPEN_SIGNUP"] {
            fixture.previous.push((key, std::env::var_os(key)));
            std::env::remove_var(key);
        }
        mail::save_config("smtp.example.com", 465, "sender@example.com", "fake", "sender@example.com", true)?;
        db::open_db()?.execute(
            "INSERT INTO users(username,pass_hash,role,display_name,created_at,email)
             VALUES('alice','!test','collaborator','Alice',1,'known@example.com')", [],
        ).map_err(|e| e.to_string())?;
        Ok(fixture)
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        for (key, value) in &self.previous {
            match value {
                Some(value) => std::env::set_var(key, value),
                None => std::env::remove_var(key),
            }
        }
    }
}

async fn wire(response: Response) -> Result<(StatusCode, Vec<u8>), String> {
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), 1024 * 1024).await
        .map_err(|e| e.to_string())?;
    Ok((status, bytes.to_vec()))
}

async fn send(email: &str, purpose: &str, letters: Letters) -> Result<(StatusCode, Vec<u8>), String> {
    let (response, task) = send_code_with(HeaderMap::new(), json!({"email":email,"purpose":purpose}),
        move |to, subject, body| {
            letters.lock().push((to.into(), subject.into(), body.into()));
            Ok(())
        }).await;
    let response = wire(response).await?;
    if let Some(task) = task { task.await.map_err(|e| e.to_string())?; }
    Ok(response)
}

fn clear_rates() -> Result<(), String> {
    db::open_db()?.execute("DELETE FROM login_attempts", []).map_err(|e| e.to_string())?;
    Ok(())
}

fn plant(email: &str, purpose: &str, phc: &str, ttl: i64, attempts: i64) -> Result<(), String> {
    db::open_db()?.execute(
        "INSERT OR REPLACE INTO email_codes(email,purpose,code_hash,attempts,created_at,expires_at)
         VALUES(?1,?2,?3,?4,?5,?6)",
        rusqlite::params![email, purpose, phc, attempts, db::now(), db::now() + ttl],
    ).map_err(|e| e.to_string())?;
    Ok(())
}

#[tokio::test]
async fn all_purposes_hide_account_state_and_deliver_only_the_expected_mail() -> Result<(), String> {
    let _fixture = Fixture::new()?;
    for purpose in ["signup", "reset", "login"] {
        clear_rates()?;
        if purpose == "signup" {
            plant("known@example.com", purpose, &auth::hash_password("123456")?, 600, 0)?;
        }
        let letters = Letters::default();
        let known = send(" KNOWN@Example.com ", purpose, letters.clone()).await?;
        let unknown = send("new@example.com", purpose, letters.clone()).await?;
        assert_eq!(known, unknown, "{purpose}: status and bytes must match");
        assert_eq!(known, (StatusCode::OK, br#"{"ok":true}"#.to_vec()));
        let delivered = letters.lock().clone();
        assert_eq!(delivered.len(), if purpose == "signup" { 2 } else { 1 });
        for (email, subject, body) in delivered {
            if purpose == "signup" && email == "known@example.com" {
                assert!(body.contains("你已有账号，请直接登录或找回密码"));
                assert!(!body.contains("验证码"));
                assert!(!subject.contains("验证码"));
            } else {
                assert!(body.contains(match purpose { "signup" => "注册账号", "login" => "登录", _ => "找回密码" }));
                let code = subject.split_whitespace().last().ok_or("no code")?;
                assert_eq!(code.len(), 6);
                mail::verify_code(&email, purpose, code)?;
                assert_eq!(mail::verify_code(&email, purpose, code), Err(mail::INVALID_CODE.into()));
            }
        }
        for email in ["known@example.com", "new@example.com"] {
            let count: i64 = db::open_db()?.query_row(
                "SELECT count(*) FROM email_codes WHERE email=?1 AND purpose=?2",
                [email, purpose], |r| r.get(0),
            ).map_err(|e| e.to_string())?;
            assert_eq!(count, 0);
        }
        let before = letters.lock().len();
        let known_retry = send("known@example.com", purpose, letters.clone()).await?;
        let new_retry = send("new@example.com", purpose, letters.clone()).await?;
        assert_eq!(known_retry, new_retry);
        assert!(!known_retry.0.is_success());
        assert_eq!(letters.lock().len(), before, "rate limit includes reminders and no-mail requests");
    }
    Ok(())
}

#[tokio::test]
async fn authority_signup_and_reset_also_hide_code_and_account_state() -> Result<(), String> {
    let _fixture = Fixture::new()?;
    std::env::set_var("POLARIS_ACCOUNT_AUTHORITY", "1");
    std::env::set_var("POLARIS_ACCOUNT_OPEN_SIGNUP", "1");
    let phc = auth::hash_password("123456")?;
    for purpose in ["signup", "reset"] {
        plant("known@example.com", purpose, &phc, 600, 0)?;
        let mut responses = vec![];
        for email in ["known@example.com", "new@example.com"] {
            let request = Json(json!({"email":email,"code":"000000"}));
            let response = if purpose == "signup" {
                account_signup(request).await
            } else {
                account_reset(request).await
            };
            responses.push(wire(response).await?);
        }
        assert_eq!(responses[0], responses[1]);
        assert_eq!(serde_json::from_slice::<Value>(&responses[0].1).map_err(|e| e.to_string())?,
            json!({"error":mail::INVALID_CODE}));
    }
    plant("new@example.com", "reset", &phc, 600, 0)?;
    let response = wire(account_reset(Json(json!({"email":"new@example.com","code":"123456"}))).await).await?;
    assert_eq!(serde_json::from_slice::<Value>(&response.1).map_err(|e| e.to_string())?,
        json!({"error":mail::INVALID_CODE}));
    Ok(())
}

#[tokio::test]
async fn response_does_not_wait_for_smtp_or_expose_delivery_failure() -> Result<(), String> {
    let _fixture = Fixture::new()?;
    for (email, purpose) in [("known@example.com", "signup"), ("new@example.com", "signup"),
        ("known@example.com", "reset"), ("known@example.com", "login")] {
        clear_rates()?;
        let (release, wait) = std::sync::mpsc::channel();
        let (response, task) = tokio::time::timeout(Duration::from_secs(2), send_code_with(
            HeaderMap::new(), json!({"email":email,"purpose":purpose}), move |_, _, _| {
                wait.recv_timeout(Duration::from_secs(5)).map_err(|e| e.to_string())?;
                Err("fake SMTP failure".into())
            },
        )).await.map_err(|e| e.to_string())?;
        let result = wire(response).await?;
        release.send(()).map_err(|e| e.to_string())?;
        task.ok_or("no background task")?.await.map_err(|e| e.to_string())?;
        assert_eq!(result, (StatusCode::OK, br#"{"ok":true}"#.to_vec()));
        assert_eq!(mail::verify_code(email, purpose, "123456"), Err(mail::INVALID_CODE.into()));
    }
    Ok(())
}

#[tokio::test]
async fn submitting_codes_has_one_error_for_missing_wrong_expired_and_exhausted_codes() -> Result<(), String> {
    let _fixture = Fixture::new()?;
    let phc = auth::hash_password("123456")?;
    let mut expected = None;
    for purpose in ["signup", "reset", "login"] {
        for (ttl, attempts, code) in [(600, 0, "000000"), (-1, 0, "123456"),
            (600, 5, "123456"), (600, 0, "")] {
            plant("known@example.com", purpose, &phc, ttl, attempts)?;
            for email in ["known@example.com", "new@example.com"] {
                let request = Json(json!({"email":email,"code":code,"username":"newuser",
                    "password":"test-password-123","newPassword":"test-password-123"}));
                let response = match purpose {
                    "signup" => collab_email_signup(request).await,
                    "reset" => collab_email_reset(request).await,
                    _ => collab_email_login(request).await,
                };
                let actual = wire(response).await?;
                assert!(!actual.0.is_success());
                assert_eq!(serde_json::from_slice::<Value>(&actual.1).map_err(|e| e.to_string())?,
                    json!({"error":mail::INVALID_CODE}));
                if let Some(expected) = &expected { assert_eq!(&actual, expected); }
                else { expected = Some(actual); }
            }
        }
    }
    // Stale valid codes cannot disclose later account binding/deletion either.
    plant("known@example.com", "signup", &phc, 600, 0)?;
    assert_eq!(mail::verify_code("known@example.com", "signup", "123456"), Err(mail::INVALID_CODE.into()));
    for purpose in ["reset", "login"] {
        plant("new@example.com", purpose, &phc, 600, 0)?;
        let request = Json(json!({"email":"new@example.com","code":"123456","newPassword":"test-password-123"}));
        let response = if purpose == "reset" { collab_email_reset(request).await } else { collab_email_login(request).await };
        assert_eq!(Some(wire(response).await?), expected);
    }
    Ok(())
}

