    tcp-request content reject if { req.ssl_hello_type 1 } !{ req.ssl_sni -i @AUTHORITY_DOMAIN@ @RELAY_DOMAIN@ }
    tcp-request content accept if { req.ssl_hello_type 1 }
    use_backend relay_tls if { req.ssl_sni -i @RELAY_DOMAIN@ }
    use_backend authority_tls if { req.ssl_sni -i @AUTHORITY_DOMAIN@ }

backend relay_tls
    mode tcp
    # 不发 PROXY header，不终止 TLS，不改 ALPN；ACME TLS-ALPN-01 原样抵达 relay。
    server relay iroh-relay:8443 resolvers docker init-addr libc,none

backend authority_tls
    mode tcp
    server caddy caddy:443 send-proxy-v2 resolvers docker init-addr libc,none

frontend http
    bind :8080
    mode http
    use_backend relay_http if { hdr(host) -i @RELAY_DOMAIN@ }
    default_backend caddy_http

backend relay_http
    mode http
    server relay iroh-relay:8080 resolvers docker init-addr libc,none

backend caddy_http
    mode http
    server caddy caddy:80 resolvers docker init-addr libc,none

frontend account_api
    bind :8081
    mode http
    # 仅容器内可达，Caddy 无条件覆盖 XFF 为 PROXY 协议确认的来源地址。
    stick-table type ip size 100k expire 1m store http_req_rate(10s)
    http-request track-sc0 req.hdr_ip(X-Forwarded-For)
    http-request deny deny_status 429 if { sc_http_req_rate(0) gt @AUTH_REQUESTS_PER_10S@ }
    default_backend authority_http

backend authority_http
    mode http
    server authority authority:8080 resolvers docker init-addr libc,none

frontend health
    bind 127.0.0.1:8404
    mode http
    monitor-uri /health
